const fs = require('fs');
const path = require('path');
const { loadSpec, DEFAULT_FILE } = require('./lib/agentic-yaml');

// Bundles the validated agentic.yaml into the worker as an ES module:
// worker/src/agentic.generated.js exports the normalized spec (SPEC) and the
// dependency-free matcher/resolver from scripts/lib/agentic.js, so the worker
// routes webhooks from the same file and code as CI and the workflows without
// needing a YAML parser (or any root dependency) at the edge.
//
// Fail closed: an invalid or missing agentic.yaml exits non-zero and leaves no
// module behind, so `wrangler deploy` (and the worker tests) cannot build.
// Run before `wrangler deploy` and before the worker tests (worker/package.json
// pretest + .github/workflows/{ci,deploy-worker}.yml).
const LIB = path.join(__dirname, 'lib', 'agentic.js');
const OUT = path.join(__dirname, '..', 'worker', 'src', 'agentic.generated.js');

function libAsEsm(source) {
  const m = /\nmodule\.exports = \{([\s\S]*?)\};\s*$/.exec(source);
  if (!m) throw new Error(`${LIB}: expected a single trailing module.exports block`);
  if (/\brequire\(/.test(source)) throw new Error(`${LIB}: must stay dependency-free (found require())`);
  return `${source.slice(0, m.index)}\nexport {${m[1]}};\n`;
}

function bundle({ file = DEFAULT_FILE, out = OUT } = {}) {
  const text = fs.readFileSync(file, 'utf8');
  const { spec, errors } = loadSpec(text);
  if (errors.length) throw new Error(`${file} is invalid:\n  ${errors.join('\n  ')}`);
  const header = [
    '// GENERATED by scripts/bundle-agentic.js from agentic.yaml and',
    '// scripts/lib/agentic.js — do not edit; regenerate instead.',
    `export const SPEC = ${JSON.stringify(spec, null, 2)};`,
    '',
  ].join('\n');
  fs.writeFileSync(out, header + libAsEsm(fs.readFileSync(LIB, 'utf8')));
  return { out, agents: Object.keys(spec.agents) };
}

if (require.main === module) {
  try {
    if (fs.existsSync(OUT)) fs.unlinkSync(OUT);
    const { out, agents } = bundle({ file: process.argv[2] });
    console.log(`${out}: bundled ${agents.length} agents (${agents.join(', ')})`);
  } catch (err) {
    console.error(`bundle-agentic: ${err.message}`);
    process.exit(1);
  }
}

module.exports = { bundle, libAsEsm, OUT };
